        /**
         * The next 48 hours, starting with the current hour.
         */hourly: [HourlyPoint], 
        /**
         * Today and up to the following 15 days, as far as the source goes.
         */daily: [DailyForecast], 
        /**
         * Unix seconds when the forecast was fetched.
